#include <iostream>
#include <memory>
#include <vector>
#include <string>

class Shape {
public:
    virtual ~Shape() {
        std::cout << "Shape destroyed\n";
    }
    virtual void draw() const = 0; // Pure virtual: Shape is abstract
    virtual double area() const = 0;
};

class Circle : public Shape {
private:
    double radius;
public:
    explicit Circle(double r) : radius(r) {}
    ~Circle() override {
        std::cout << "Circle destroyed\n";
    }
    void draw() const override {
        std::cout << "Drawing Circle with radius: " << radius << "\n";
    }
    double area() const override {
        return 3.14159 * radius * radius;
    }
};

class Rectangle : public Shape {
private:
    double width, height;
public:
    Rectangle(double w, double h) : width(w), height(h) {}
    ~Rectangle() override {
        std::cout << "Rectangle destroyed\n";
    }
    void draw() const override {
        std::cout << "Drawing Rectangle: " << width << "x" << height << "\n";
    }
    double area() const override {
        return width * height;
    }
};

int main() {
    // Polymorphic processing using modern smart pointers
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>(3.0));
    shapes.push_back(std::make_unique<Rectangle>(4.0, 5.0));

    for (const auto& shape : shapes) {
        shape->draw();
        std::cout << "Area: " << shape->area() << "\n";
    }
    // Proper cleanup verified as vector clears
    shapes.clear();
    return 0;
}

#include <iostream>
#include <vector>
#include <memory>
#include <typeinfo>

class Employee {
public:
    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << "Employee";
    }
};

class CommissionEmployee : public Employee {
protected:
    double sales{5000.0};
    double rate{0.06};
public:
    double earnings() const override { return sales * rate; }
    void print() const override {
        std::cout << "CommissionEmployee [Sales: " << sales << "]";
    }
};

class BasePlusCommissionEmployee : public CommissionEmployee {
private:
    double baseSalary{1000.0};
public:
    double earnings() const override {
        return baseSalary + CommissionEmployee::earnings();
    }
    void print() const override {
        std::cout << "BasePlusCommissionEmployee [Base: " << baseSalary << "]";
    }
    void setBaseSalary(double s) { baseSalary = s; }
    double getBaseSalary() const { return baseSalary; }
};

int main() {
    std::vector<std::unique_ptr<Employee>> staff;
    staff.push_back(std::make_unique<CommissionEmployee>());
    staff.push_back(std::make_unique<BasePlusCommissionEmployee>());

    for (const auto& emp : staff) {
        std::cout << "RTTI type name: " << typeid(*emp).name() << "\n";

        // Downcast to access derived-only method
        auto* basePlus = dynamic_cast<BasePlusCommissionEmployee*>(emp.get());
        if (basePlus != nullptr) {
            std::cout << "--> Found BasePlus: bumping base salary by 10%\n";
            basePlus->setBaseSalary(basePlus->getBaseSalary() * 1.10);
        }

        emp->print();
        std::cout << " | Earnings: $" << emp->earnings() << "\n";
    }
    return 0;
}
